namespace doc_example_TreeView_2 {
struct FolderPane final : gf::Component {
    std::shared_ptr<gf::TreeView> tree =
        gf::make_control<gf::TreeView>(gf::StableId("pane.folders"));
    std::string current;
    int collapses = 0;

    FolderPane() {
        gf::on((*tree).selection_changed(), *this, &FolderPane::on_selected);
        gf::on((*tree).expansion_changed(), *this, &FolderPane::on_expansion);
    }
    void on_selected(const gf::TreeSelectionChange& change) {
        current = change.current_id;
    }
    void on_expansion(const gf::TreeExpansionChange& change) {
        if (!change.expanded) ++collapses;
    }
};

void example() {
    FolderPane pane;
    std::vector<gf::TreeViewItem> folders;
    folders.push_back({"src", "src", 0U, true, true});
    folders.push_back({"src.core", "core", 1U});
    (*pane.tree).set_items(folders);
    (*pane.tree).selected_id = "src.core";   // pane.current is "src.core"
    (*pane.tree).set_expanded("src", false);    // collapses, then pane.current is "src"
}
}  // namespace doc_example_TreeView_2

namespace doc_example_UpdateScope_1 {
void example() {
    std::shared_ptr<gf::Panel> root = gf::make_control<gf::Panel>(gf::StableId("root"));
    std::shared_ptr<gf::Label> status = gf::make_control<gf::Label>(gf::StableId("status"), "Ready");
    std::shared_ptr<gf::Button> cancel = gf::make_control<gf::Button>(gf::StableId("cancel"), "Cancel");
    (*root).add_child(status);
    (*root).add_child(cancel);
    gf::Window window(root, gf::Size{320.0, 80.0});
    window.perform_layout();
    window.reset_activity_metrics();
    {
        gf::UpdateScope scope = window.begin_update();
        (*status).set_bounds({8.0, 8.0, 200.0, 24.0});
        (*status).text = "Working";
        (*cancel).set_bounds({216.0, 6.0, 96.0, 28.0});
    }   // one layout flush here
    gf::MetricsSnapshot metrics = window.metrics_snapshot();   // metrics.flush_count == 1
    static_cast<void>(metrics);
}
}  // namespace doc_example_UpdateScope_1

