namespace doc_example_Value_2 {
struct VolumeLimit final : gf::Component {
    void check(int candidate) {
        if (candidate > 100) throw std::out_of_range("volume above 100");
    }
};

void example() {
    gf::Value<int> volume(50);
    VolumeLimit limit;
    gf::on(volume.validating(), limit, &VolumeLimit::check);
    volume.set(80);            // accepted
    try {
        volume.set(120);       // rejected before it is stored
    } catch (const std::out_of_range&) {
    }
    // volume.get() == 80
}
}  // namespace doc_example_Value_2

namespace doc_example_Window_1 {
struct Dialog final : gf::Component {
    std::shared_ptr<gf::Panel> root = gf::make_control<gf::Panel>(gf::StableId("dialog"));
    std::shared_ptr<gf::Button> ok = gf::make_control<gf::Button>(gf::StableId("dialog.ok"), "OK");
    int clicks = 0;

    Dialog() {
        (*ok).set_bounds({20.0, 20.0, 80.0, 28.0});
        (*root).add_child(ok);
        gf::on((*ok).clicked(), *this, &Dialog::on_ok);
    }
    void on_ok() { ++clicks; }
};

void example() {
    Dialog dialog;
    gf::Window window(dialog.root, gf::Size{240.0, 120.0});
    window.perform_layout();
    gf::PointerEvent down{gf::PointerAction::down, gf::PointerButton::primary, {40.0, 30.0}};
    gf::PointerEvent up{gf::PointerAction::up, gf::PointerButton::primary, {40.0, 30.0}};
    window.dispatch_pointer(down);   // focuses and captures the button
    window.dispatch_pointer(up);     // released over it: dialog.clicks == 1
}
}  // namespace doc_example_Window_1

namespace doc_example_Window_2 {
struct ShowDone final {
    std::shared_ptr<gf::Label> status;
    void operator()() const { (*status).text = "Done"; }
};

void example() {
    std::shared_ptr<gf::Panel> root = gf::make_control<gf::Panel>(gf::StableId("root"));
    std::shared_ptr<gf::Label> status =
        gf::make_control<gf::Label>(gf::StableId("status"), "Working");
    (*root).add_child(status);
    gf::Window window(root, gf::Size{320.0, 40.0});

    gf::DispatchOperation posted = window.begin_invoke(ShowDone{status});
    gf::DispatchDrainResult turn = window.drain_posted_work();
    // turn.invoked == 1, and the label now reads "Done"
    static_cast<void>(posted);
    static_cast<void>(turn);
}
}  // namespace doc_example_Window_2

namespace doc_example_Worker_1 {
struct Sum final {
    int limit = 0;
    long long total = 0;   // read by the owner only after join
};

void add_up(const gf::CancellationFlag& cancel, void* context) {
    Sum& sum = *static_cast<Sum*>(context);
    for (int value = 1; value <= sum.limit && !cancel.requested(); ++value) {
        sum.total += value;
    }
}

void example() {
    Sum sum;
    sum.limit = 1000;
    gf::Worker worker(add_up, &sum);   // declared after its context
    worker.join();                     // sum.total == 500500
}
}  // namespace doc_example_Worker_1

namespace doc_example_Worker_2 {
void parse_input(const gf::CancellationFlag&, void*) {
    throw std::runtime_error("malformed input");
}

void example() {
    gf::Worker worker(parse_input, nullptr);
    try {
        worker.join();
    } catch (const std::runtime_error&) {
        // reported once
    }
    worker.join();   // already reported: returns normally
}
}  // namespace doc_example_Worker_2

namespace doc_example_XmlElement_1 {
void example() {
    gf::XmlReadResult read = gf::read_xml(
        "<layout format=\"2\"><panel id=\"tools.output\"/></layout>");
    if (!read) {
        return;   // read.error, read.position.line and read.position.column say why
    }
    const gf::XmlAttribute* format = read.root.find_attribute("format");   // "2"
    std::size_t panels = read.root.children.size();                       // 1
    gf::XmlWriteResult written = gf::write_xml(read.root);
    // written.text:
    // <?xml version="1.0" encoding="UTF-8"?>
    // <layout format="2">
    //   <panel id="tools.output"/>
    // </layout>
    static_cast<void>(format);
    static_cast<void>(panels);
}
}  // namespace doc_example_XmlElement_1

namespace doc_example_XmlElement_2 {
void example() {
    gf::XmlElement root;
    root.name = "settings";
    root.attributes.push_back(gf::XmlAttribute{.name = "theme", .value = "a & b"});
    gf::XmlElement note;
    note.name = "note";
    note.text = "x < y";
    root.children.push_back(note);
    gf::XmlWriteResult written = gf::write_xml(root);   // escapes & and <

    gf::XmlElement mixed = root;
    mixed.text = "text beside a child";
    gf::XmlWriteResult refused = gf::write_xml(mixed);
    bool is_mixed = refused.error == gf::XmlError::mixed_content;   // true
    static_cast<void>(written);
    static_cast<void>(is_mixed);
}
}  // namespace doc_example_XmlElement_2

namespace doc_example_XmlLimits_1 {
void example() {
    gf::XmlLimits limits;
    limits.maximum_depth = 2;
    gf::XmlReadResult shallow = gf::read_xml("<a><b/></a>", limits);        // accepted
    gf::XmlReadResult deep = gf::read_xml("<a><b><c/></b></a>", limits);   // refused
    bool refused = deep.error == gf::XmlError::depth_exceeded;              // true
    static_cast<void>(shallow);
    static_cast<void>(refused);
}
}  // namespace doc_example_XmlLimits_1

namespace {

int run(const char* name, void (*example)()) {
    try {
        example();
    } catch (const std::exception& error) {
        std::fprintf(stderr, "FAIL %s: %s\n", name, error.what());
        return 1;
    }
    std::fprintf(stdout, "ok   %s\n", name);
    return 0;
}

}  // namespace

